func TestDocsRejectsAnUnknownTopic(t *testing.T) {
	t.Parallel()
	for _, args := range [][]string{{"docs"}, {"docs", "nope"}, {"docs", "events", "extra"}, {"docs", "flows", "--nope"}} {
		var stdout, stderr bytes.Buffer
		if code := run(commands(), tools(nil), nil, args, &stdout, &stderr); code != 2 || stdout.Len() != 0 ||
			stderr.String() != "usage: monacoctl docs errors|events|flows [--feature-map]|logs\n" {
			t.Fatalf("%q: code=%d stdout=%q stderr=%q", args, code, stdout.String(), stderr.String())
		}
	}
}

func TestDocsFlowsRendersTheTSV(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name, tsv      string
		code           int
		stdout, stderr string
	}{
		{
			"valid", flows.Header + "\n" + pingRow + "\n", 0,
			"| # | Flow | Command / trigger | Events | Consumers |\n| --- | --- | --- | --- | --- |\n" +
				"| 01 | Ping | `Ping` on `poller:platform.retention` | `system.pinged` | none |\n", "",
		},
		{"malformed", flows.Header + "\n01\tPing\n", 1, "", flows.Dir + "/01.tsv:2: has 2 columns, want 10\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			var stdout, stderr bytes.Buffer
			code := docsFlows(envWith(t, tc.tsv).Repo, flows.Markdown, &stdout, &stderr)
			if code != tc.code || stdout.String() != tc.stdout || stderr.String() != tc.stderr {
				t.Fatalf("code=%d stdout=%q stderr=%q", code, stdout.String(), stderr.String())
			}
		})
	}
}

func TestDocsFlowsFeatureMapListsEachOutcomeWithItsTestAndVerifyCommand(t *testing.T) {
	t.Parallel()
	row := "00\tPing\tsystem\tPOST /v1/system/pings\tRecordPing\tsystem.pinged\tsystem.echo\t" +
		"ok;InvalidInput;crash:after-publish\tverified\tdocs/flows.md#ping"
	var stdout, stderr bytes.Buffer
	code := docsFlows(envWith(t, flows.Header+"\n"+row+"\n").Repo, flows.FeatureMap, &stdout, &stderr)
	want := "# Feature map\n\n" +
		"Generated by `monacoctl docs flows --feature-map` from `packages/flows/backend/*.tsv`. Do not edit; " +
		"`scripts/ci/ready.sh` fails when it is stale.\n\n" +
		"## Flow 00: Ping\n\n" +
		"- Module: `system`\n- Status: `verified`\n- Trigger: `POST /v1/system/pings`\n" +
		"- Command: `RecordPing`\n- Events: `system.pinged`\n- Consumers: `system.echo`\n" +
		"- Doc: `docs/flows.md#ping`\n\n" +
		"| Outcome | Test | Verify |\n| --- | --- | --- |\n" +
		"| `ok` | `TestFlow00_RecordPing_OK` | `monacoctl verify flow 00 --outcome ok` |\n" +
		"| `InvalidInput` | `TestFlow00_RecordPing_InvalidInput` | `monacoctl verify flow 00 --outcome InvalidInput` |\n" +
		"| `crash:after-publish` | `TestFlow00_RecordPing_CrashAfterPublish` | " +
		"`monacoctl verify flow 00 --outcome crash:after-publish` |\n"
	if code != 0 || stdout.String() != want || stderr.Len() != 0 {
		t.Fatalf("code=%d stderr=%q stdout=\n%s\nwant\n%s", code, stderr.String(), stdout.String(), want)
	}
}

func TestDocsFlowsFeatureMapWritesNoneForAnEmptyCommandOrConsumerList(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	code := docsFlows(envWith(t, flows.Header+"\n"+pingRow+"\n").Repo, flows.FeatureMap, &stdout, &stderr)
	for _, line := range []string{
		"- Command: `Ping`\n",
		"- Consumers: none\n",
		"- Trigger: `poller:platform.retention`\n",
	} {
		if code != 0 || !strings.Contains(stdout.String(), line) {
			t.Fatalf("code=%d stderr=%q stdout=\n%s\nwant a line %q", code, stderr.String(), stdout.String(), line)
		}
	}
	noCommand := strings.NewReplacer("\tPing\tsystem.pinged", "\t\tsystem.pinged", "\tbuilt\t", "\tplanned\t").
		Replace(pingRow)
	stdout.Reset()
	code = docsFlows(envWith(t, flows.Header+"\n"+noCommand+"\n").Repo, flows.FeatureMap, &stdout, &stderr)
	if code != 0 || !strings.Contains(stdout.String(), "- Command: none\n") {
		t.Fatalf("code=%d stderr=%q stdout=\n%s\nwant Command: none", code, stderr.String(), stdout.String())
	}
}

func TestDocsFlowsFailsWhenTheTSVIsMissing(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	code := docsFlows(fstest.MapFS{}, flows.Markdown, &stdout, &stderr)
	if code != 1 || stdout.Len() != 0 || !strings.HasPrefix(stderr.String(), "monacoctl docs flows: ") {
		t.Fatalf("code=%d stdout=%q stderr=%q", code, stdout.String(), stderr.String())
	}
}

func TestDocsLogsPrintsTheMessageCatalogWithoutConfig(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	if code := run(commands(), tools(nil), nil, []string{"docs", "logs"}, &stdout, &stderr); code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	if !strings.HasPrefix(stdout.String(), "| Message | Required attrs |\n") ||
		!strings.Contains(stdout.String(), "| `boot.stopped` | `service`, `err` |\n") {
		t.Fatalf("stdout = %q, want the registry as a Markdown table", stdout.String())
	}
}

type failingWriter struct{}

func (failingWriter) Write([]byte) (int, error) { return 0, io.ErrClosedPipe }

func TestDocsLogsWriteFailureExits1(t *testing.T) {
	t.Parallel()
	var stderr bytes.Buffer
	code := docsLogs(failingWriter{}, &stderr)
	if code != 1 || !strings.HasPrefix(stderr.String(), "monacoctl docs logs: observability.WriteCatalog: internal") {
		t.Fatalf("docs logs = %d %q, want 1 and the wrapped error", code, stderr.String())
	}
}

func TestDocsErrorsPrintsTheCodeTable(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	if code := run(commands(), tools(nil), nil, []string{"docs", "errors"}, &stdout, &stderr); code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	out := stdout.String()
	for _, want := range []string{
		"| Code | HTTP status | Retryable | Alerts | Message |\n| --- | --- | --- | --- | --- |\n",
		"| `db_unavailable` | 503 | yes | no | The service is temporarily unavailable. Try again shortly. |\n",
		"| `version_conflict` | 409 | no | no | This changed since you last loaded it. Refresh and try again. |\n",
		"| `panic` | 500 | no | yes | Something went wrong. |\n",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("stdout =\n%s\nwant a line %q", out, want)
		}
	}
	if rows := strings.Count(out, "\n| `"); rows != len(errs.All()) {
		t.Fatalf("got %d code rows, want %d", rows, len(errs.All()))
	}
}
